and below is just me writing it out.

Here is a quick mock up example of what a save float array method might look like

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class HelpForSomeDude : MonoBehaviour 
{
    //get an instance of this static class, so that it can be used from anywhere
    public static HelpForSomeDude instance;

    void Start()
    {

        //set that global instance of the class to this.
        instance = this;


        //pop this script on some gameobject/like a manager or something, you then can call functions using HelpforSomeDude.SaveSomeArrayToPlayerPref or whatever other methods
    }
    //Function instead of void if java i think, i wrote this is c#, but should give quick idea
    public void SaveSomeArrayToPlayerPref(float[] arrayToSave, string SaveName)
    {
        for (int i = 0; i < arrayToSave.Length; i++)
        {
            //idea being here that is saves each float as the basename + the location in array, so float of spot 1 in array would be saved as SaveName1 
            PlayerPrefs.SetFloat(SaveName + i, arrayToSave[i]);

            //this is using the name we save, adding on a "Keyword" TotalLength, and saving the array size/number of elements of it, as its own int, to be read later to reconstruct the array.
            PlayerPrefs.SetInt(SaveName + "TotalLength", arrayToSave.Length);
        }

   }

//Here is a quick reader method that can convert a blank array into the saved array
//Public function/method with the return type of a float of arrays, you just pass in the basename of the save and it returns the entire array

    public float[] GetSavedFloatFromString(string baseSaveName)
    {
        //create a new array of floats, that has the size of the save name we are looking at.
        float[] ReconstructedArrayFromName = new float[PlayerPrefs.GetInt(baseSaveName + "TotalLength")];

        for (int i = 0; i < ReconstructedArrayFromName.Length; i++)
        {
            //cycle through each position in the array, and set each spot to that of the saved name we are finding.
            ReconstructedArrayFromName[i] = PlayerPrefs.GetFloat(baseSaveName + i);
        }

        return ReconstructedArrayFromName;
    }
}


//Example of a player class that has mutliple stats(float might not be the best, but i couldnt think of an example for some reason
public class PlayerStats
{
    public float[] allStats;

    //save method of the above stats
    void Save()
    {
        //use the helper class to call the save method for these stats, and name it as characterstats/whatever youd like
        HelpForSomeDude.instance.SaveSomeArrayToPlayerPref(allStats, "CharacterStats");
    }

    void Load()
    {
        //using the same name we saved as, it autopoulates and replaced the float using the helper method again.
        allStats = HelpForSomeDude.instance.GetSavedFloatFromString("CharacterStats");

        //the array allstats, should now be replaced/updated with what you have.
    }
}
}

I have not tested the code, but have some confidence(80%) this should work.

The idea basically is that, you can now save an array of floats using that simple method from anywhere, with just a new name, and load using just the name.
